const input = $input.first().json;
const body = input.body || input;
const message = body.message || body.command || body.text || 'Kiểm tra trạng thái hệ thống';
const adminId = body.adminId || 'super_admin';

return [{
  json: {
    message,
    adminId
  }
}];

const command = $('2. Trích Xuất Lệnh Điều Khiển').first().json.message.toLowerCase();
const currentConfig = $input.first().json.data || $input.first().json || {};

let action = 'query';
let updatePayload = {};
let reply = '';

// 1. Phân tích lệnh đóng/mở quyền toàn trang
if (command.includes('bảo trì') || command.includes('maintenance')) {
  const enable = !command.includes('tắt') && !command.includes('mở');
  action = 'toggle_system';
  updatePayload = { maintenance_mode: enable };
  reply = enable ? '⛔ ĐÃ BẬT CHẾ ĐỘ BẢO TRÌ TOÀN TRANG!' : '✅ ĐÃ TẮT CHẾ ĐỘ BẢO TRÌ (Hệ thống mở lại bình thường)!';
} else if (command.includes('khoá tạo đơn') || command.includes('khoá đơn free')) {
  action = 'toggle_system';
  updatePayload = { lock_free_orders: true };
  reply = '🔒 ĐÃ KHOÁ TÍNH NĂNG TẠO ĐƠN VỚI TÀI KHOẢN FREE!';
} else if (command.includes('mở tạo đơn') || command.includes('mở đơn free')) {
  action = 'toggle_system';
  updatePayload = { lock_free_orders: false };
  reply = '🔓 ĐÃ MỞ KHOÁ TÍNH NĂNG TẠO ĐƠN CHO TÀI KHOẢN FREE!';
} else if (command.includes('khoá nợ') || command.includes('khoá công nợ')) {
  action = 'toggle_system';
  updatePayload = { lock_free_debts: true };
  reply = '🔒 ĐÃ KHOÁ TÍNH NĂNG QUẢN LÝ CÔNG NỢ VỚI TÀI KHOẢN FREE!';
} else if (command.includes('mở nợ') || command.includes('mở công nợ')) {
  action = 'toggle_system';
  updatePayload = { lock_free_debts: false };
  reply = '🔓 ĐÃ MỞ KHOÁ TÍNH NĂNG CÔNG NỢ CHO TÀI KHOẢN FREE!';
} else {
  // Lệnh tra cứu trạng thái
  reply = `📊 BÁO CÁO TRẠNG THÁI NEXUS CONTROL:\n` +
    `• Chế độ bảo trì: ${currentConfig.maintenance_mode ? '🔴 ĐANG BẬT' : '🟢 ĐANG TẮT'}\n` +
    `• Khoá đơn Free: ${currentConfig.lock_free_orders ? '🔒 ĐANG KHOÁ' : '🟢 MỞ'}\n` +
    `• Khoá nợ Free: ${currentConfig.lock_free_debts ? '🔒 ĐANG KHOÁ' : '🟢 MỞ'}\n` +
    `• Khoá Sheet Free: ${currentConfig.lock_free_sheets ? '🔒 ĐANG KHOÁ' : '🟢 MỞ'}\n` +
    `• Tự động khoá AI: ${currentConfig.ai_auto_lock ? '🛡️ BẬT' : '⚪ TẮT'}`;
}

return [{
  json: {
    action,
    updatePayload,
    reply,
    shouldUpdate: Object.keys(updatePayload).length > 0
  }
}];

